import React from "react";
import { Box, Typography, Stack, Paper } from "@mui/material";
import cafeImg from "../../assets/cafeInside.png";
import { useTheme } from "@mui/material/styles";

function Home() {
  const theme = useTheme();
  return (
    <Box sx={{mx: "auto"}}>
      <Box sx={{ width: "100%", my: 0, maxHeight: 50, bgcolor: theme.palette.primary.blushPink  }}/>
      {/* Main hero photo 
      <Box component="img" src={cafeImg} alt=" Cafe inner image" sx={{width: "100%", my: 0, height: "auto", objectFit: "cover"}} /> 
*/}
    </Box>
  );
}

export default Home;
